cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x}
# 2x2 squares, three L triominoes from observed orientations
shapes={'1':[(0,0),(0,1),(1,0),(1,1)],'2':[(0,1),(1,0),(1,1)],'3':[(0,0),(0,1),(1,1)],'4':[(0,0),(1,0),(1,1)]}
placements=[]
for color,shape in shapes.items():
 for r in range(7):
  for c in range(7):
   piece={(r+dr,c+dc) for dr,dc in shape}
   if piece<=cells: placements.append((color,piece))
sols=[]
def solve(rem, pieces):
 if not rem:
  sols.append(pieces); return
 cell=min(rem)
 for col,p in placements:
  if cell in p and p<=rem: solve(rem-p,pieces+[(col,p)])
solve(cells,[])
len(sols), [[(col, sorted(p)) for col,p in sol] for sol in sols[:3]]
